```
public class OrderPayloadParser {
    public static Order parse(String body) {
        if (isBlank(body)) {
            throw new PayloadException('Order payload must not be null or blank');
        }
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Order payload is not valid JSON', e);
        }
        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Order payload must be a JSON object');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();
        order.orderNumber = getRequiredText('number', root.get('number'));
        order.orderDate = parseIsoDate(root.get('date'));
        order.currencyCode = getOptionalText('currency', root.get('currency'));

        Object customer = root.get('customer');
        if (customer instanceof Map<String, Object>) {
            order.customerEmail = getOptionalText('customer.email', ((Map<String, Object>) customer).get('email'));
        } else {
            order.customerEmail = null;
        }

        List<Line> lines = parseLines(root.get('lines'));
        order.lines = lines;
        order.total = calculateTotal(lines);
        return order;
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order must not be null');
        }
        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total == null ? 0 : order.total;
        JSONGenerator g = JSON.createGenerator();
        g.writeStartObject();
        g.writeFieldName('number');
        if (order.orderNumber == null) {
            g.writeNull();
        } else {
            g.writeString(order.orderNumber);
        }
        g.writeFieldName('status');
        g.writeString('RECEIVED');
        g.writeFieldName('lineCount');
        g.writeNumber(lineCount);
        g.writeFieldName('total');
        g.writeNumber(total);
        g.writeEndObject();
        return g.getAsString();
    }

    private static List<Line> parseLines(Object linesValue) {
        List<Line> lines = new List<Line>();
        if (linesValue == null) {
            return lines;
        }
        if (!(linesValue instanceof List<Object>)) {
            return lines;
        }
        List<Object> rawLines = (List<Object>) linesValue;
        for (Integer i = 0; i < rawLines.size(); i++) {
            Object rawLine = rawLines[i];
            if (rawLine == null || !(rawLine instanceof Map<String, Object>)) {
                throw new PayloadException('Each line must be a JSON object');
            }
            Map<String, Object> lineMap = (Map<String, Object>) rawLine;
            Line line = new Line();
            line.sku = getRequiredText('sku', lineMap.get('sku'));
            line.quantity = getRequiredPositiveInteger('quantity', lineMap.get('quantity'));
            line.unitPrice = getRequiredNonNegativeDecimal('unitPrice', lineMap.get('unitPrice'));
            line.discount = getOptionalDecimal('discount', lineMap.get('discount'));
            line.lineTotal = calculateLineTotal(line.quantity, line.unitPrice, line.discount);
            lines.add(line);
        }
        return lines;
    }

    private static Decimal calculateTotal(List<Line> lines) {
        Decimal total = 0;
        if (lines != null) {
            for (Line line : lines) {
                if (line != null && line.lineTotal != null) {
                    total = total + line.lineTotal;
                }
            }
        }
        return total;
    }

    private static Decimal calculateLineTotal(Integer quantity, Decimal unitPrice, Decimal discount) {
        if (quantity == null || unitPrice == null) {
            return 0;
        }
        if (discount == null) {
            discount = 0;
        }
        Decimal raw = quantity * unitPrice * (1 - discount);
        return roundTwoPlacesHalfUp(raw);
    }

    private static Decimal roundTwoPlacesHalfUp(Decimal value) {
        if (value == null) {
            return 0;
        }
        Decimal scaled = value * 100;
        Decimal cents;
        if (scaled >= 0) {
            cents = Math.floor(scaled + 0.5);
        } else {
            cents = Math.ceil(scaled - 0.5);
        }
        return cents / 100;
    }

    private static String getRequiredText(String fieldName, Object value) {
        if (value == null) {
            throw new PayloadException('Missing ' + fieldName);
        }
        if (value instanceof String) {
            String s = (String) value;
            if (isBlank(s)) {
                throw new PayloadException('Blank ' + fieldName);
            }
            return s;
        }
        if (value instanceof Boolean || value instanceof List<Object> || value instanceof Map<String, Object>) {
            throw new PayloadException('Invalid ' + fieldName);
        }
        String s = String.valueOf(value);
        if (isBlank(s)) {
            throw new PayloadException('Blank ' + fieldName);
        }
        return s;
    }

    private static String getOptionalText(String fieldName, Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            String s = (String) value;
            return isBlank(s) ? null : s;
        }
        if (value instanceof Boolean || value instanceof List<Object> || value instanceof Map<String, Object>) {
            return null;
        }
        String s = String.valueOf(value);
        return isBlank(s) ? null : s;
    }

    private static Integer getRequiredPositiveInteger(String fieldName, Object value) {
        Decimal d = toDecimal(fieldName, value, true, true);
        if (d == null) {
            throw new PayloadException('Missing ' + fieldName);
        }
        if (d <= 0) {
            throw new PayloadException('Non-positive ' + fieldName);
        }
        if (d != Math.floor(d)) {
            throw new PayloadException('Invalid ' + fieldName);
        }
        if (d > Integer.MAX_VALUE) {
            throw new PayloadException('Invalid ' + fieldName);
        }
        return Integer.valueOf(d);
    }

    private static Decimal getRequiredNonNegativeDecimal(String fieldName, Object value) {
        Decimal d = toDecimal(fieldName, value, true, true);
        if (d == null || d < 0) {
            throw new PayloadException('Missing or negative ' + fieldName);
        }
        return d;
    }

    private static Decimal getOptionalDecimal(String fieldName, Object value) {
        Decimal d = toDecimal(fieldName, value, false, false);
        return d == null ? 0 : d;
    }

    private static Decimal toDecimal(String fieldName, Object value, boolean required, boolean strict) {
        if (value == null) {
            if (required || strict) {
                throw new PayloadException('Missing ' + fieldName);
            }
            return null;
        }
        try {
            if (value instanceof Decimal) {
                return (Decimal) value;
            }
            String s;
            if (value instanceof String) {
                s = (String) value;
            } else {
                s = String.valueOf(value);
            }
            if (isBlank(s)) {
                if (required || strict) {
                    throw new PayloadException('Missing ' + fieldName);
                }
                return null;
            }
            s = s.trim();
            return Decimal.valueOf(s);
        } catch (Exception e) {
            if (strict) {
                throw new PayloadException('Invalid ' + fieldName, e);
            }
            return null;
        }
    }

    private static Date parseIsoDate(Object value) {
        if (value == null) {
            return null;
        }
        String s = value instanceof String ? (String) value : String.valueOf(value);
        if (isBlank(s)) {
            return null;
        }
        s = s.trim();
        try {
            if (s.length() != 10) {
                return null;
            }
            if (s.charAt(4) != '-' || s.charAt(7) != '-') {
                return null;
            }
            Integer year = Integer.valueOf(s.substring(0, 4));
            Integer month = Integer.valueOf(s.substring(5, 7));
            Integer day = Integer.valueOf(s.substring(8, 10));
            if (month < 1 || month > 12) {
                return null;
            }
            Integer daysInMonth = getDaysInMonth(year, month);
            if (day < 1 || day > daysInMonth) {
                return null;
            }
            return Date.newInstance(year, month, day);
        } catch (Exception e) {
            return null;
        }
    }

    private static Integer getDaysInMonth(Integer year, Integer month) {
        switch (month) {
            when (1, 3, 5, 7, 8, 10, 12) return 31;
            when (4, 6, 9, 11) return 30;
            when (2) return isLeapYear(year) ? 29 : 28;
            otherwise return 31;
        }
    }

    private static Boolean isLeapYear(Integer year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    private static Boolean isBlank(String s) {
        return s == null || s.trim().length() == 0;
    }

