public with sharing class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> toInsert = new List<Lead>();
        List<Integer> inputIndexes = new List<Integer>();
        Map<String, Boolean> seenEmails = new Map<String, Boolean>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead is null.');
                continue;
            }

            if (lead.LeadSource == null || lead.LeadSource.trim().isEmpty()) {
                lead.LeadSource = 'Web';
            }

            String emailKey = normalizeEmail(lead.Email);
            if (emailKey != null) {
                if (seenEmails.containsKey(emailKey)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                    continue;
                }
                seenEmails.put(emailKey, true);
            }

            toInsert.add(lead);
            inputIndexes.add(i);
        }

        if (!toInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(toInsert, false);
            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer inputIndex = inputIndexes[j];
                if (sr.isSuccess()) {
                    result.insertedIds.add(sr.getId());
                } else {
                    result.errorsByIndex.put(inputIndex, getJoinedErrorMessage(sr));
                }
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }

    private static String normalizeEmail(String email) {
        if (email == null) return null;
        String trimmed = email.trim();
        if (trimmed.isEmpty()) return null;
        return trimmed.toLowerCase();
    }

    private static String getJoinedErrorMessage(Database.SaveResult saveResult) {
        List<Database.Error> errors = saveResult.getError();
        if (errors == null || errors.isEmpty()) {
            return 'Unknown database error.';
        }
        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            messages.add(error.getMessage());
        }
        return String.join(messages, '; ');
    }
}
