public with sharing class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new ImportResult();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> inputIndexes = new List<Integer>();
        Map<String, Boolean> seenEmails = new Map<String, Boolean>();

        for (Integer index = 0; index < leads.size(); index++) {
            Lead lead = leads[index];

            if (lead == null) {
                result.errorsByIndex.put(index, 'Lead is null.');
                continue;
            }

            if (lead.LeadSource == null || lead.LeadSource.trim().isEmpty()) {
                lead.LeadSource = 'Web';
            }

            String emailKey = normalizeEmail(lead.Email);
            if (emailKey != null) {
                if (seenEmails.containsKey(emailKey)) {
                    result.errorsByIndex.put(index, 'Duplicate email in import: ' + emailKey);
                    continue;
                }
                seenEmails.put(emailKey, true);
            }

            leadsToInsert.add(lead);
            inputIndexes.add(index);
        }

        if (!leadsToInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(leadsToInsert, false);
            for (Integer i = 0; i < saveResults.size(); i++) {
                Database.SaveResult saveResult = saveResults[i];
                Integer inputIndex = inputIndexes[i];

                if (saveResult.isSuccess()) {
                    result.insertedIds.add(saveResult.getId());
                } else {
                    result.errorsByIndex.put(inputIndex, joinErrorMessages(saveResult));
                }
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        return trimmed.toLowerCase();
    }

    private static String joinErrorMessages(Database.SaveResult saveResult) {
        List<Database.Error> errors = saveResult.getError();
        if (errors == null || errors.isEmpty()) {
            return '';
        }

        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            if (error == null) {
                continue;
            }
            String message = error.getMessage();
            if (message != null) {
                messages.add(message);
            }
        }
        return String.join(messages, '; ');
    }
}
```

