public class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        Map<String, FB_Shipment_Event__e> latestEventByOrderNumber = new Map<String, FB_Shipment_Event__e>();

        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }

            String orderNumber = event.Order_Number__c.trim().upperCase();
            latestEventByOrderNumber.put(orderNumber, event);
        }

        if (latestEventByOrderNumber.isEmpty()) {
            return;
        }

        List<FB_Sales_Order__c> orders = [
            SELECT Id,
                   Order_Number__c,
                   Status__c,
                   Tracking_Number__c,
                   Carrier__c,
                   Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :latestEventByOrderNumber.keySet()
        ];

        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        Date shipDate = Date.today();

        for (FB_Sales_Order__c order : orders) {
            if (String.isBlank(order.Order_Number__c)) {
                continue;
            }

            if (order.Status__c != null && order.Status__c.equalsIgnoreCase('Cancelled')) {
                continue;
            }

            String orderNumber = order.Order_Number__c.trim().upperCase();
            FB_Shipment_Event__e event = latestEventByOrderNumber.get(orderNumber);

            if (event == null) {
                continue;
            }

            order.Status__c = 'Shipped';
