private static Map<Id, AggregateResult> getAggregateResults(Set<Id> accountIds) {
    Map<Id, AggregateResult> result = new Map<Id, AggregateResult>();
    List<Id> idList = new List<Id>(accountIds);
    Integer chunkSize = 200;
    for (Integer i=0; i<idList.size(); i+=chunkSize) {
        Set<Id> chunk = new Set<Id>(idList.sublist(i, Math.min(i+chunkSize, idList.size())));
