private static Map<Id, AggregateResult> calculateTotals(Set<Id> accountIds) {
    Map<Id, AggregateResult> totals = new Map<Id, AggregateResult>();
    List<Id> idList = new List<Id>(accountIds);
    for (Integer i = 0; i < idList.size(); i += CHUNK_SIZE) {
        Integer end = (i + CHUNK_SIZE < idList.size()) ? i + CHUNK_SIZE : idList.size();
        Set<Id> chunk = new Set<Id>(idList.sublist(i, end));
        List<AggregateResult> results = [
            SELECT AccountId,
                   SUM(Amount) pipelineTotal,
                   COUNT(Id) opportunityCount
            FROM Opportunity
            WHERE AccountId IN :chunk AND IsClosed = false
            GROUP BY AccountId
        ];
        for (AggregateResult ar : results) {
            totals.put((Id) ar.get('AccountId'), ar);
        }
    }
    return totals;
}

private static Map<Id, Account> loadCurrentAccounts(Set<Id> accountIds) {
    Map<Id, Account> current = new Map<Id, Account>();
    List<Id> idList = new List<Id>(accountIds);
    for (Integer i = 0; i < idList.size(); i += CHUNK_SIZE) {
        Integer end = (i + CHUNK_SIZE < idList.size()) ? i + CHUNK_SIZE : idList.size();
        Set<Id> chunk = new Set<Id>(idList.sublist(i, end));
        List<Account> accounts = [SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c FROM Account WHERE Id IN :chunk];
        for (Account acc : accounts) current.put(acc.Id, acc);
    }
    return current;
}

