public class OpportunityPipelineHandler {
    private static final Integer CHUNK_SIZE = 200;
    private static Boolean isExecuting = false;

    public static void execute() {
        if (isExecuting) {
            return;
        }
        isExecuting = true;
        try {
            Set<Id> accountIds = new Set<Id>();
            if (Trigger.isInsert) {
                for (Opportunity opp : Trigger.new) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            } else if (Trigger.isUpdate) {
                for (Opportunity opp : Trigger.old) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
                for (Opportunity opp : Trigger.new) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            } else if (Trigger.isDelete) {
                for (Opportunity opp : Trigger.old) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            } else if (Trigger.isUndelete) {
                for (Opportunity opp : Trigger.old) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
                for (Opportunity opp : Trigger.new) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }

            if (accountIds.isEmpty()) {
                return;
            }

            Map<Id, AggregateResult> totalsByAccount = calculateTotals(accountIds);
            Map<Id, Account> currentAccounts = loadCurrentAccounts(accountIds);
            List<Account> accountsToUpdate = new List<Account>();

            for (Id accountId : accountIds) {
                Account current = currentAccounts.get(accountId);
                if (current == null) {
                    continue;
                }

                AggregateResult total = totalsByAccount.get(accountId);
                Decimal pipeline = getPipeline(total);
                Integer count = getCount(total);

                if (hasChanged(current, pipeline, count)) {
                    Account acc = new Account(
                        Id = accountId,
                        FB_Open_Pipeline__c = pipeline,
                        FB_Open_Opportunities__c = count
                    );
                    accountsToUpdate.add(acc);
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                updateAccounts(accountsToUpdate);
            }
        } finally {
            isExecuting = false;
        }
    }

    private static Map<Id, AggregateResult> calculateTotals(Set<Id> accountIds) {
        Map<Id, AggregateResult> totals = new Map<Id, AggregateResult>();
        List<Id> accountList = new List<Id>(accountIds);

        for (Integer i = 0; i < accountList.size(); i += CHUNK_SIZE) {
            Integer end = (i + CHUNK_SIZE < accountList.size()) ? i + CHUNK_SIZE : accountList.size();
            Set<Id> chunk = new Set<Id>(accountList.sublist(i, end));

            List<AggregateResult> results = [
                SELECT AccountId,
                       SUM(Amount) pipelineTotal,
                       COUNT(Id) opportunityCount
                FROM Opportunity
                WHERE AccountId IN :chunk AND IsClosed = false
                GROUP BY AccountId
            ];

            for (AggregateResult ar : results) {
                Id accountId = (Id) ar.get('AccountId');
                totals.put(accountId, ar);
            }
        }

        return totals;
    }

    private static Map<Id, Account> loadCurrentAccounts(Set<Id> accountIds) {
        Map<Id, Account> current = new Map<Id, Account>();
        List<Id> accountList = new List<Id>(accountIds);

        for (Integer i = 0; i < accountList.size(); i += CHUNK_SIZE) {
            Integer end = (i + CHUNK_SIZE < accountList.size()) ? i + CHUNK_SIZE : accountList.size();
            Set<Id> chunk = new Set<Id>(accountList.sublist(i, end));

            List<Account> accounts = [
                SELECT Id,
                       FB_Open_Pipeline__c,
                       FB_Open_Opportunities__c
                FROM Account
                WHERE Id IN :chunk
            ];

            for (Account acc : accounts) {
                current.put(acc.Id, acc);
            }
        }

        return current;
    }

    private static Decimal getPipeline(AggregateResult ar) {
        if (ar == null) {
            return 0;
        }
        Object value = ar.get('pipelineTotal');
        return value == null ? 0 : (Decimal) value;
    }

    private static Integer getCount(AggregateResult ar) {
        if (ar == null) {
            return 0;
        }
        Object value = ar.get('opportunityCount');
        return value == null ? 0 : (Integer) value;
    }

    private static Boolean hasChanged(Account current, Decimal pipeline, Integer count) {
        Boolean pipelineChanged = current.FB_Open_Pipeline__c == null
            || current.FB_Open_Pipeline__c != pipeline;
        Boolean countChanged = current.FB_Open_Opportunities__c == null
            || current.FB_Open_Opportunities__c != count;
        return pipelineChanged || countChanged;
    }

    private static void updateAccounts(List<Account> accounts) {
        for (Integer i = 0; i < accounts.size(); i += CHUNK_SIZE) {
            Integer end = (i + CHUNK_SIZE < accounts.size()) ? i + CHUNK_SIZE : accounts.size();
            update accounts.sublist(i, end);
        }
    }
}
