Apex code:
public class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }
        if (validAccountIds.isEmpty()) {
            return result;
        }

        for (Id accountId : validAccountIds) {
            result.put(accountId, 0);
        }

        Integer currentYear = Date.today().year();
        Date startOfYear = Date.parse(String.valueOf(currentYear).leftPad(4, '0') + '-01-01');
        Date endOfYear = Date.parse(String.valueOf(currentYear + 1).leftPad(4, '0') + '-01-01');

        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) TotalAmount
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate >= :startOfYear
                AND CloseDate < :endOfYear
                AND AccountId IN :validAccountIds
            GROUP BY AccountId
        ];

        for (AggregateResult aggregate : aggregates) {
            Id accountId = (Id) aggregate.get('AccountId');
            if (accountId == null) {
                continue;
            }
            Decimal totalAmount = (Decimal) aggregate.get('TotalAmount');
            result.put(accountId, totalAmount == null ? (Decimal) 0 : totalAmount);
        }

        return result;
    }
}

